-- 10 rubros y 115 residuos típicos por rubro. Borrador de Claude (basis = inferencia, verified = false): lo valida Jazmín.
insert into public.industry_sectors (id, name_es, name_en, description_es, prompt_context_es, display_order) values
('energia_electrica','Generación eléctrica','Electric power generation','Centrales térmicas, hidroeléctricas, solares, eólicas y subestaciones.','El trabajador está en una central eléctrica. Son frecuentes los aceites dieléctricos y lubricantes, baterías de respaldo, lámparas de mercurio, equipos que pudieran contener PCB, aislamientos con asbesto, cenizas de carbón y envases de químicos de tratamiento de agua.',1),
('transporte','Transporte y logística','Transport and logistics','Flotas, terminales, talleres de mantenimiento y almacenes de distribución.','El trabajador está en una empresa de transporte o logística. Predominan aceites y filtros usados, baterías, neumáticos, anticongelantes, trapos con hidrocarburo y envases de lubricantes.',2),
('mineria','Minería','Mining','Operaciones mineras, plantas de beneficio y laboratorios metalúrgicos.','El trabajador está en una operación minera. Son frecuentes los aceites y grasas, reactivos y soluciones con cianuro o ácidos, explosivos vencidos, lodos con metales pesados y neumáticos de gran tamaño.',3),
('oficinas','Oficinas y servicios administrativos','Offices and administrative services','Oficinas corporativas, bancos y centros administrativos.','El trabajador está en una oficina. Predominan papel, cartón y plásticos limpios, equipos electrónicos, cartuchos de tóner, pilas y fluorescentes. Casi todo es no peligroso salvo los residuos electrónicos, tóner, pilas y lámparas.',4),
('construccion','Construcción y demolición','Construction and demolition','Obras civiles, edificación y demolición.','El trabajador está en una obra. Predominan escombros y concreto, madera, pinturas, solventes, adhesivos, envases contaminados, aceites de maquinaria y, en demoliciones, materiales con asbesto.',5),
('manufactura','Manufactura e industria','Manufacturing and industry','Plantas industriales, talleres metalmecánicos y de procesos.','El trabajador está en una planta de manufactura. Son frecuentes los solventes, pinturas, aceites de corte, lodos de tratamiento de metales, ácidos y álcalis, envases contaminados y chatarra metálica.',6),
('hidrocarburos','Hidrocarburos (petróleo y gas)','Oil and gas','Exploración, refinación, almacenamiento y estaciones de servicio.','El trabajador está en una instalación de hidrocarburos. Predominan lodos de tanques, aguas aceitosas, aceites usados, catalizadores gastados, solventes y envases de aditivos.',7),
('salud','Salud y laboratorios','Health care and laboratories','Hospitales, clínicas, laboratorios y centros veterinarios.','El trabajador está en un establecimiento de salud o laboratorio. Hay residuos biocontaminados, punzocortantes, medicamentos vencidos y reactivos químicos. Ante la duda con un residuo en contacto con fluidos o sangre, tratarlo como peligroso.',8),
('agroindustria','Agricultura y agroindustria','Agriculture and agro-industry','Cultivos, packing, procesamiento de alimentos y ganadería.','El trabajador está en una operación agrícola o agroindustrial. Predominan envases de plaguicidas, agroquímicos vencidos, plásticos agrícolas, residuos orgánicos y aceites de maquinaria.',9),
('comercio','Comercio y servicios','Retail and services','Tiendas, centros comerciales, restaurantes, hoteles y farmacias.','El trabajador está en un comercio o servicio. Predominan cartón, plástico, orgánicos y vidrio. Los peligrosos son pilas, fluorescentes, aerosoles, productos de limpieza vencidos, medicamentos vencidos y equipos electrónicos.',10);

